<script setup>import {ref,reactive,onMounted} from 'vue';import {useRouter} from 'vue-router';import {api,useSession,toast,time} from '../core';import State from '../components/State.vue';const session=useSession(),router=useRouter(),tab=ref('profile'),profile=ref(null),notes=ref([]),error=ref(''),loading=ref(false),busy=ref(false),filter=ref('ALL'),page=ref(1),noteTotal=ref(0),form=reactive({nickname:'',bio:''}),password=reactive({oldPassword:'',newPassword:'',confirmPassword:''});async function load(){loading.value=true;error.value='';try{profile.value=await api('/me');form.nickname=profile.value.nickname;form.bio=profile.value.bio;await notifications()}catch(e){error.value=e.message}finally{loading.value=false}}async function notifications(){try{const r=await api('/me/notifications?'+new URLSearchParams({filter:filter.value,page:page.value,size:10}));notes.value=r.items;noteTotal.value=r.total}catch(e){toast(e.message,true)}}async function save(){busy.value=true;try{profile.value=await api('/me','PUT',{...form,expectedProfileVersion:profile.value.profileVersion});session.user.nickname=profile.value.nickname;toast('资料已保存')}catch(e){toast(e.message,true);if(e.status===409)await load()}finally{busy.value=false}}async function change(){busy.value=true;try{await api('/me/password','POST',password);session.clear();toast('密码已修改，请重新登录');router.push('/login')}catch(e){toast(e.message,true)}finally{busy.value=false;password.oldPassword='';password.newPassword='';password.confirmPassword=''}}async function read(n){try{await api('/me/notifications/'+n.id+'/read','PUT');await notifications()}catch(e){toast(e.message,true)}}onMounted(load);</script><template><section class="shell section"><p class="eyebrow">YOUR LITTLE CORNER</p><h1>我的寻爪</h1><div class="account-layout"><aside class="panel side-menu"><div class="avatar big">{{session.user?.nickname?.slice(0,1)}}</div><h3>{{session.user?.nickname}}</h3><span class="badge">{{session.user?.role==='ADMIN'?'平台管理员':'寻爪成员'}}</span><button :class="{active:tab==='profile'}" @click="tab='profile'">个人资料</button><button :class="{active:tab==='notifications'}" @click="tab='notifications'">站内通知</button><button :class="{active:tab==='security'}" @click="tab='security'">账号安全</button><RouterLink to="/adoptions">我的领养 →</RouterLink><RouterLink to="/orders">我的订单 →</RouterLink></aside><div class="panel"><State :loading="loading" :error="error" @retry="load"/><template v-if="profile&&!loading&&!error"><form v-if="tab==='profile'" class="form-stack" @submit.prevent="save"><h2>个人资料</h2><p class="muted">简单介绍自己，让每一次沟通更温暖。</p><label>账号<input :value="profile.account" readonly></label><label>昵称<input v-model="form.nickname" required maxlength="30"></label><label>个人简介<textarea v-model="form.bio" maxlength="200" rows="5"></textarea></label><p class="hint">加入时间：{{time(profile.createdAt)}}</p><button class="btn" :disabled="busy">保存资料</button></form><form v-if="tab==='security'" class="form-stack" @submit.prevent="change"><h2>账号安全</h2><label>当前密码<input v-model="password.oldPassword" type="password" autocomplete="current-password" required></label><label>新密码<input v-model="password.newPassword" type="password" autocomplete="new-password" required></label><label>确认新密码<input v-model="password.confirmPassword" type="password" autocomplete="new-password" required></label><p class="hint">新密码8–32个字符，包含字母和数字。修改后全部旧会话失效。</p><button class="btn" :disabled="busy">修改密码</button></form><section v-if="tab==='notifications'"><div class="row between"><h2>站内通知</h2><select v-model="filter" aria-label="通知筛选" @change="page=1;notifications()"><option value="ALL">全部通知</option><option value="UNREAD">未读通知</option></select></div><div v-if="!notes.length" class="state">暂时没有通知</div><article class="notification" v-for="n in notes" :key="n.id"><div class="row between"><h3>{{n.title}} <span v-if="!n.readAt" class="unread-dot"></span></h3><small>{{time(n.createdAt)}}</small></div><p class="preserve">{{n.body}}</p><button v-if="!n.readAt" class="text-button" @click="read(n)">标记为已读</button><span v-else class="hint">已读</span></article><div class="pagination"><button :disabled="page===1" class="btn secondary small" @click="page--;notifications()">上一页</button><span>{{page}}</span><button :disabled="page*10>=noteTotal" class="btn secondary small" @click="page++;notifications()">下一页</button></div></section></template></div></div></section></template>
